#include <print>
#include <optional>
#include <variant>
#include <expected>
#include <string>

std::expected<int, std::string> safe_divide(int a, int b);   // 除数是 0 要把原因交给调用者，所以选 expected

int main() {
    std::optional<char> grade = 'A';
    std::variant<int, std::string> who = 7;
    std::expected<int, std::string> r = 99;
    std::println("optional 里: {}", grade.value_or('?'));
    std::println("variant 现在是 int 吗: {}", std::holds_alternative<int>(who));
    std::println("expected 里: {}", r.value_or(-1));
    return 0;
}

